package com.example.rokidkeyboardbridge;
import android.graphics.*;import java.io.*;import java.util.zip.ZipFile;
public final class CoolSmileCanvasTest {
 public static void main(String[]args)throws Exception{int checked=0;File dir=new File(args[1]);dir.mkdirs();try(ZipFile zip=new ZipFile(args[0])){
 for(int id=0;id<FullBodyRealisticFeatures.ALL.length;id++)if(CoolSmilePolicy.supports(id)||(id>=282&&id<=287)){
  float[] f=FullBodyFaceAnimator.features(id),original=FullBodyRealisticFeatures.ALL[id];if((CoolSmilePolicy.supports(id)&&(f[7]!=1||f[13]!=1))||Math.abs(f[2]-original[2])>.0001||Math.abs(f[8]-original[8])>.0001)throw new AssertionError("anchors "+id);
  for(int sample:new int[]{1,2}){Bitmap source=FullBodyRealisticAssets.decode(zip,id,sample);if(Math.abs(source.getWidth()*sample-(FullBodyRealisticAssets.REGIONS[id][2]-FullBodyRealisticAssets.REGIONS[id][0]))>sample-1)throw new AssertionError("dimensions "+id);
   if(sample==1&&id>=282&&id<=287){int[] region=FullBodyRealisticAssets.REGIONS[id];Bitmap sheet;try(InputStream input=zip.getInputStream(zip.getEntry("assets/"+FullBodyRealisticAssets.NAMES[FullBodyRealisticAssets.SHEET[id]]))){sheet=BitmapFactory.decodeStream(input);}Bitmap originalCrop=Bitmap.createBitmap(sheet,region[0],region[1],region[2]-region[0],region[3]-region[1]);if(!source.sameAs(originalCrop))throw new AssertionError("seated original anatomy not restored "+id);if(FullBodyFaceAnimator.features(id)!=FullBodyRealisticFeatures.ALL[id])throw new AssertionError("seated original landmarks "+id);originalCrop.recycle();sheet.recycle();checked++;}
   int w=source.getWidth(),h=source.getHeight();int[] before=new int[w*h];source.getPixels(before,0,w,0,0,w,h);
   for(int state=0;state<2;state++){Bitmap rendered=source.copy(Bitmap.Config.ARGB_8888,true);FullBodyFaceAnimator animator=new FullBodyFaceAnimator();animator.draw(new Canvas(rendered),source,id,state==0?4600:220,state==1);int[] after=new int[w*h];rendered.getPixels(after,0,w,0,0,w,h);int changed=0;for(int j=0;j<after.length;j++)if(before[j]!=after[j]){changed++;if(j/w>(f[15]+f[16]+6)*h/f[1])throw new AssertionError("body changed "+id);}if(state==1&&id>=282&&id<=287){int upper=0,lower=0;float lipY=(f[15]+f[16]*.03f)*h/f[1];for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++){int j=yy*w+xx;int delta=Math.abs((before[j]&255)-(after[j]&255));if(delta>32&&Math.abs(xx-f[14]*w/f[0])<f[16]*.5f*w/f[0]){double angle=Math.toRadians(f[17]),localY=-(xx-f[14]*w/f[0])*Math.sin(angle)+(yy-f[15]*h/f[1])*Math.cos(angle);if(localY+1<f[16]*.03f*h/f[1])upper++;else lower++;}}if(upper>0)throw new AssertionError("seated upper lip moved "+id+" sample "+sample+" changes "+upper);if(sample==1&&lower==0)throw new AssertionError("seated lower lip has no movement "+id);}
    if(changed==0&&(state==1||f[7]==1||f[13]==1))throw new AssertionError("no "+(state==0?"blink":"mouth")+" "+id+" sample "+sample);checked++;
    if(sample==1&&(id==1||(id>=282&&id<=287))){try(FileOutputStream out=new FileOutputStream(new File(dir,"pose-"+id+"-"+state+".png"))){rendered.compress(Bitmap.CompressFormat.PNG,100,out);}}
    rendered.recycle();animator.clear();
   }
   if(sample==1){float faceBottom=(f[15]+Math.max(f[16]*.25f,f[18])+4)/f[1];float[] flow=new float[(FullBodyMorphRenderer.COLUMNS+1)*(FullBodyMorphRenderer.ROWS+1)*2],zero=new float[flow.length];java.util.Arrays.fill(flow,.08f);Bitmap still=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888),moving=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Paint paint=new Paint(3);FullBodyMorphRenderer morph=new FullBodyMorphRenderer();morph.draw(new Canvas(still),source,paint,zero,.45f,w,h,1,null,false,faceBottom,true);morph.draw(new Canvas(moving),source,paint,flow,.45f,w,h,1,null,false,faceBottom,true);int[] aa=new int[w*h],bb=new int[w*h];still.getPixels(aa,0,w,0,0,w,h);moving.getPixels(bb,0,w,0,0,w,h);int faceChange=0,bodyChange=0;for(int j=0;j<aa.length;j++)if(aa[j]!=bb[j]){if(j/w<(faceBottom+.03f)*h)faceChange++;else bodyChange++;}if(faceChange!=0||bodyChange==0)throw new AssertionError("rigid face / moving body "+id+" "+faceChange+"/"+bodyChange);checked++;still.recycle();moving.recycle();}
   source.recycle();
  }
 }
 if(CoolSmilePolicy.seatedPose(FullBodyPoseCatalog.Kind.JOY,true,1)!=168||CoolSmilePolicy.seatedPose(FullBodyPoseCatalog.Kind.JOY,false,1)!=1||CoolSmilePolicy.seatedPose(FullBodyPoseCatalog.Kind.REFUSE,true,2)!=2)throw new AssertionError("posture/objection");
 System.out.println("PASS "+checked+" Canvas cases: 33 cool and six restored seated frames, blink/mouth at two scales and rigid head under body morph; seated joy and objection priority");
 }}
}
